package com.example.firstapplication.learn_jetpack_compose.performancekillers

import androidx.compose.foundation.border
import androidx.compose.foundation.layout.Arrangement
import androidx.compose.foundation.layout.Column
import androidx.compose.foundation.layout.fillMaxWidth
import androidx.compose.foundation.layout.padding
import androidx.compose.foundation.shape.RoundedCornerShape
import androidx.compose.material3.Button
import androidx.compose.material3.Text
import androidx.compose.runtime.Composable
import androidx.compose.runtime.getValue
import androidx.compose.runtime.key
import androidx.compose.runtime.mutableStateOf
import androidx.compose.runtime.remember
import androidx.compose.runtime.setValue
import androidx.compose.ui.Alignment
import androidx.compose.ui.Modifier
import androidx.compose.ui.graphics.Color
import androidx.compose.ui.tooling.preview.Preview
import androidx.compose.ui.unit.dp
import com.example.firstapplication.learn_jetpack_compose.ui.theme.FirstApplicationTheme

/*
Problem: Recomposition occurs while reordering items while not using LazyColumn/LazyRow.
Goal: Recomposition shouldn't happen while reordering items regardless of the layout or parent.
*/

data class FormField(val id : String, val label: String, val color: Color)

@Composable
fun DynamicForm(modifier: Modifier = Modifier) {
    var fields by remember {
        mutableStateOf(listOf(
            FormField("name", "Name", Color.Red),
            FormField("email", "Email", Color.Gray),
        ))
    }

    Column(
        modifier = modifier.fillMaxWidth(),
        horizontalAlignment = Alignment.CenterHorizontally,
        verticalArrangement = Arrangement.spacedBy(6.dp)
    ) {
        Button(onClick = { fields = fields.reversed() }) {
            Text("Swap Items")
        }
        /* // ❌ Bad
        fields.forEach { field ->
            FormFieldItem(field)
        }
        */
        // ✅ Good
        fields.forEach { field ->
            key(field.id) {
                FormFieldItem(field)
            }
        }
    }
}


@Composable
fun FormFieldItem(field: FormField, modifier: Modifier = Modifier) {
    Text(
        text = field.label,
        modifier = modifier
            .fillMaxWidth()
            .padding(16.dp)
            .border(
                width = 1.dp,
                color = field.color,
                shape = RoundedCornerShape(4.dp)
            )
            .padding(16.dp),
        color = field.color
    )
}


@Preview(showBackground = true)
@Composable
fun DynamicFormPreview() {
    FirstApplicationTheme {
        DynamicForm(Modifier.padding(24.dp))
    }
}

package com.example.firstapplication.learn_jetpack_compose.performancekillers
import androidx.compose.foundation.border import androidx.compose.foundation.layout.Arrangement import androidx.compose.foundation.layout.Column import androidx.compose.foundation.layout.fillMaxWidth import androidx.compose.foundation.layout.padding import androidx.compose.foundation.shape.RoundedCornerShape import androidx.compose.material3.Button import androidx.compose.material3.Text import androidx.compose.runtime.Composable import androidx.compose.runtime.getValue import androidx.compose.runtime.key import androidx.compose.runtime.mutableStateOf import androidx.compose.runtime.remember import androidx.compose.runtime.setValue import androidx.compose.ui.Alignment import androidx.compose.ui.Modifier import androidx.compose.ui.graphics.Color import androidx.compose.ui.tooling.preview.Preview import androidx.compose.ui.unit.dp import com.example.firstapplication.learn_jetpack_compose.ui.theme.FirstApplicationTheme
/* * ============================================================ * PERFORMANCE KILLER #3 — Not Using `key()` When Rendering Lists * ============================================================ * * PROBLEM: * - When rendering a list of composables using `forEach` (or any loop) * WITHOUT `key()`, Compose identifies each item purely by its **position** * in the composition tree. * - If items are reordered, added, or removed, Compose cannot tell which * composable maps to which item — so it recomposes ALL items from scratch. * - Example (Bad): * fields.forEach { field -> * FormFieldItem(field) // ❌ identified by index, not identity * } * - When "Swap Items" is clicked, both items recompose unnecessarily, * and any internal state (e.g., text input, scroll position) is LOST or RESET. * * HOW TO RESOLVE: * - Wrap each item with `key(uniqueId) { }` so Compose tracks items by * their **stable identity**, not their position. * - Example (Good): * fields.forEach { field -> * key(field.id) { * FormFieldItem(field) // ✅ identified by field.id * } * } * - Now when items are reordered, Compose moves existing compositions * instead of destroying and recreating them — preserving internal state. * * CONCEPTS TO KNOW: * 1. **Composition Tree & Position-Based Identity:** * - By default, Compose identifies composables by their call-site position * in the tree. Changing order = different position = full recomposition. * * 2. **`key(value) { }` Composable:** * - Assigns a stable, unique identity to a composable subtree. * - When the list is reordered, Compose matches old and new compositions * by key and simply moves them — avoiding unnecessary recomposition. * - The key must be unique and stable (e.g., an ID, not an index). * * 3. **LazyColumn / LazyRow — `key` parameter:** * - In lazy lists, `key` is provided directly in the `items()` DSL: * items(fields, key = { it.id }) { field -> FormFieldItem(field) } * - Same concept, built into the lazy list API. * * 4. **Why NOT use index as key:** * - Using the item's index as the key is equivalent to having no key — * positions still change on reorder, causing the same problem. * - Always use a stable, unique property of the item (e.g., database ID). * ============================================================ */
data class FormField(val id : String, val label: String, val color: Color)
@Composable fun DynamicForm(modifier: Modifier = Modifier) { var fields by remember { mutableStateOf(listOf( FormField("name", "Name", Color.Red), FormField("email", "Email", Color.Gray), )) }
Column( modifier = modifier.fillMaxWidth(), horizontalAlignment = Alignment.CenterHorizontally, verticalArrangement = Arrangement.spacedBy(6.dp) ) { Button(onClick = { fields = fields.reversed() }) { Text("Swap Items") } /* // ❌ Bad fields.forEach { field -> FormFieldItem(field) } */ // ✅ Good fields.forEach { field -> key(field.id) { FormFieldItem(field) } } } }
@Composable fun FormFieldItem(field: FormField, modifier: Modifier = Modifier) { Text( text = field.label, modifier = modifier .fillMaxWidth() .padding(16.dp) .border( width = 1.dp, color = field.color, shape = RoundedCornerShape(4.dp) ) .padding(16.dp), color = field.color ) }
@Preview(showBackground = true) @Composable fun DynamicFormPreview() { FirstApplicationTheme { DynamicForm(Modifier.padding(24.dp)) } }

plugins {
    alias(libs.plugins.android.application) // android.application plugin tells Gradle that you're building an Android app (not a library)
    alias(libs.plugins.kotlin.android) // kotlin.android plugin enables Kotlin language support in your Android project.
    alias(libs.plugins.kotlin.compose) // This is the **Kotlin Compiler Plugin for Jetpack Compose**
    alias(libs.plugins.kotlin.hilt)
    id("org.jetbrains.kotlin.plugin.parcelize") // But this is working
    //    alias(libs.plugins.kotlin.parcelize) // This is Not Working
    kotlin("kapt")
    // id("com.example.newcodegen")
}
/* Just A Custom Plugin */
apply<CustomPlugin>()

class CustomPlugin : Plugin<Project> {
    override fun apply(target: Project) {
        println("Hello Tech Universe !!! I'm a custom plugin")
    }
}

println("${layout.buildDirectory} ,,, $rootDir")
// Configure Code GenPlugin Task Needed paths
/*
codeGen {
    sourceJsonFilePath = "/Users/sabari-23133/AndroidStudioProjects/FirstApplication/app/src/main/java/com/example/firstapplication/util/property/UiAutomationIdentifiers.json"
    targetKtFilePath = "/Users/sabari-23133/AndroidStudioProjects/FirstApplication/app/src/main/java/com/example/firstapplication/util/uiauto/UiAutomationIdentifiers.kt"
}
*/

android {
    namespace = "com.example.firstapplication" // Used for generated code and R class.
    compileSdk = 35 /* this tells Gradle which version of the Android SDK to use when compiling your code. */

    defaultConfig {
        applicationId = "com.example.firstapplication" // Used to identify your app on device & Play Store
        minSdk = 27
        targetSdk = 35 // For which Android SDK version the app was designed and tested for.
        versionCode = 1 // versionCode is for machines
        versionName = "1.0" // versionName is for humans

        testInstrumentationRunner = "androidx.test.runner.AndroidJUnitRunner" // specifies which framework to use for running automated tests on actual devices or emulators.
    }


    println("<------------ flavorDimensions: $flavorDimensions")
    flavorDimensions += listOf("paidStatus", "style")
    productFlavors {
        create("free") {
            applicationIdSuffix = ".free" /* applicationIdSuffix allows you to install
            - multiple variants of the same app on one device simultaneously.
            Practical benefit: Developers can test release builds without losing their debug build with test data.
            Testers can compare multiple versions without switching.
            */
            dimension = "paidStatus"
        }

        create("paid") {
            applicationIdSuffix = ".paid"
            dimension = "paidStatus"
        }

        create("blue") {
            dimension = "style"
        }
        create("violet") {
            dimension = "style"
        }
    }

    buildTypes { // This defines different configurations for building your app
        debug {
            isMinifyEnabled = false  /*  means the build process won't shrink your code or remove unused parts
            (you'd typically enable this for production to reduce app size and prevent security risks of reverse engineering) */
            buildConfigField("String", "BASE_URL", "\"https://dev.com\"")
        }

        create("staging") { // Let's Assume We Need To Ship The APK to Testing Team But No Need For Some Release Level Build Processes
            // You Can See This Variant In Build Variants
            isMinifyEnabled = true
            buildConfigField("String", "BASE_URL", "\"https://dev.com\"")
            signingConfig = signingConfigs.getByName("debug")
        }

        release {
            isMinifyEnabled = true
            proguardFiles( // specify configuration files for code obfuscation and optimization.
                getDefaultProguardFile("proguard-android-optimize.txt"),
                "proguard-rules.pro"
            )
            buildConfigField("String", "BASE_URL", "\"https://release.com\"")
            signingConfig = signingConfigs.getByName("debug")
            enableAndroidTestCoverage = false
        }
    }
    compileOptions {
        sourceCompatibility = JavaVersion.VERSION_11
        targetCompatibility = JavaVersion.VERSION_11
    }
    kotlinOptions {
        jvmTarget = "11"
        freeCompilerArgs = listOf("-XXLanguage:+PropertyParamAnnotationDefaultTargetMode")
    }
    buildFeatures {
        compose = true
        viewBinding = true
        buildConfig = true
    }
}

dependencies {
    // 1. implementation dependencies are included in your final app
    // 2. testImplementation are only used for unit tests running on your development machine
    // 3. androidTestImplementation are for tests running on Android devices
    // 4. debugImplementation are only included in debug builds
    implementation(project(":mylibrary"))
    implementation(libs.androidx.core.ktx)
    implementation(libs.androidx.lifecycle.runtime.ktx)
    implementation(libs.androidx.activity.compose)
    implementation(platform(libs.androidx.compose.bom))
    implementation(libs.androidx.ui)
    implementation(libs.androidx.ui.graphics)
    implementation(libs.androidx.ui.tooling.preview)
    implementation(libs.androidx.material3)
    implementation(libs.androidx.constraintlayout)
    implementation(libs.androidx.appcompat)
    implementation(libs.material)
    implementation(libs.androidx.activity)
    implementation(libs.androidx.fragment)
    implementation(libs.androidx.recyclerview)
    implementation(libs.androidx.viewpager2)
    implementation(libs.androidx.navigation.fragment.ktx)
    implementation(libs.androidx.navigation.ui.ktx)
    implementation(libs.androidx.legacy.support.v4)
    implementation(libs.androidx.navigation.fragment)
    implementation(libs.androidx.navigation.ui)

    // Force a compatible JavaPoet version
    constraints {
        implementation("com.squareup:javapoet:1.13.0") {
            because("Resolve JavaPoet version conflicts between annotation processors")
        }
    }

    // Room
    implementation(libs.androidx.room.runtime)

    debugImplementation(libs.androidx.ui.tooling)
    debugImplementation(libs.androidx.ui.test.manifest)
    // ksp(libs.androidx.room.compiler)
    kapt(libs.androidx.room.compiler)
    // annotationProcessor("androidx.room:room-compiler:2.7.2") The issue: You’re coding in Kotlin, but annotationProcessor is for Java.

    // HILT
    implementation(libs.hilt.android)
    kapt(libs.hilt.compiler)

    // For image loading and caching
    implementation("com.github.bumptech.glide:glide:4.15.1")
    kapt("com.github.bumptech.glide:compiler:4.15.1")

    // For HTTP requests
    implementation("com.squareup.retrofit2:retrofit:2.9.0")
    implementation("com.squareup.retrofit2:converter-gson:2.9.0")
    implementation("com.squareup.okhttp3:logging-interceptor:4.11.0")
    implementation("com.squareup.okhttp3:okhttp:4.11.0")

    // For coroutines (recommended for async operations)
    implementation("org.jetbrains.kotlinx:kotlinx-coroutines-core:1.7.2")
    implementation("org.jetbrains.kotlinx:kotlinx-coroutines-android:1.7.2")

    // ViewModel and lifecycle
    implementation("androidx.lifecycle:lifecycle-viewmodel-ktx:2.7.0")
    implementation("androidx.lifecycle:lifecycle-livedata-ktx:2.7.0")
    implementation("androidx.lifecycle:lifecycle-runtime-ktx:2.7.0")
    implementation("androidx.activity:activity-ktx:1.8.2")

    // Splash Screen
    implementation("androidx.core:core-splashscreen:1.0.1")

    // androidx.preference
    implementation("androidx.preference:preference:1.2.1")

    // App Widget
    implementation(libs.widget.glance)
    implementation(libs.widget.glance.material3)

    // JC Reorderable Library
    implementation("sh.calvin.reorderable:reorderable:3.0.0")

    androidTestImplementation("androidx.test.ext:junit-ktx:1.1.3")
    androidTestImplementation("androidx.test:runner:1.6.2")

    androidTestImplementation("androidx.test.espresso:espresso-core:3.6.1")
    androidTestImplementation("androidx.test.espresso:espresso-contrib:3.6.1")
    androidTestImplementation("androidx.test.espresso:espresso-intents:3.6.1")
    implementation("androidx.test.espresso:espresso-idling-resource:3.6.1") //Will Be Used In App Code
    androidTestImplementation("androidx.test.espresso:espresso-idling-resource:3.6.1")
    androidTestImplementation(platform(libs.androidx.compose.bom))
    androidTestImplementation(libs.androidx.ui.test.junit4)
}
